const define = (name, Component) => {
  if (!customElements.get(name)) customElements.define(name, Component);
};

const escapeHtml = (value = '') => String(value)
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const parseOptions = (element) => {
  try {
    return element.options || JSON.parse(element.getAttribute('options') || '[]');
  } catch {
    return [];
  }
};

const emit = (element, name, detail) => element.dispatchEvent(
  new CustomEvent(name, { bubbles: true, detail }),
);

const placePopover = (trigger, popover) => {
  const triggerRect = trigger.getBoundingClientRect();
  const popoverRect = popover.getBoundingClientRect();
  const gap = 8;
  popover.dataset.popoverY = innerHeight - triggerRect.bottom >= popoverRect.height + gap || triggerRect.top < popoverRect.height + gap ? 'down' : 'up';
  popover.dataset.popoverX = innerWidth - triggerRect.left >= popoverRect.width || triggerRect.right < popoverRect.width ? 'right' : 'left';
};

// Icon objects cross HTML attribute boundaries as JSON, never as SVG markup.
const escapeIcon = (value) => escapeHtml(value && typeof value === 'object' ? JSON.stringify(value) : value);

// Sidebar sections scroll, so their tooltips use the top layer to avoid clipping.
const sidebarTooltip = (host, trigger, label) => {
  const tip = document.createElement('span');
  tip.className = 'se-tooltip__bubble se-sidebar-tooltip';
  tip.setAttribute('role', 'tooltip');
  tip.setAttribute('popover', 'manual');
  tip.textContent = label;
  host.append(tip);
  const hide = () => { if (tip.matches(':popover-open')) tip.hidePopover(); };
  const show = () => {
    if (!host.closest('[data-sidebar-collapsed]') || trigger.matches(':disabled')) return;
    tip.showPopover();
    const rect = trigger.getBoundingClientRect();
    tip.style.left = `${Math.min(rect.right + 8, innerWidth - tip.offsetWidth - 8)}px`;
    tip.style.top = `${Math.max(8, Math.min(rect.top + (rect.height - tip.offsetHeight) / 2, innerHeight - tip.offsetHeight - 8))}px`;
  };
  trigger.addEventListener('pointerenter', show);
  trigger.addEventListener('pointerleave', hide);
  trigger.addEventListener('focus', show);
  trigger.addEventListener('blur', hide);
  trigger.addEventListener('click', hide);
  trigger.addEventListener('keydown', event => { if (event.key === 'Escape') hide(); });
};

// Keep popup content in its component for inherited themes, but paint above clipping containers.
const openPopup = (trigger, popup, close, matchWidth = false) => {
  popup.setAttribute('popover', 'manual');
  popup.classList.add('se-popup');
  const position = () => {
    const rect = trigger.getBoundingClientRect();
    popup.style.width = matchWidth ? Math.min(rect.width, innerWidth - 16) + 'px' : '';
    popup.style.maxWidth = Math.max(0, innerWidth - 16) + 'px';
    popup.style.maxHeight = Math.max(0, innerHeight - 16) + 'px';
    const height = popup.offsetHeight;
    const below = innerHeight - rect.bottom - 8;
    const above = rect.top - 8;
    const down = below >= height || below >= above;
    popup.style.maxHeight = Math.max(0, down ? below - 8 : above - 8) + 'px';
    popup.style.left = Math.max(8, Math.min(rect.left, innerWidth - popup.offsetWidth - 8)) + 'px';
    popup.style.top = Math.max(8, down ? rect.bottom + 8 : rect.top - 8 - popup.offsetHeight) + 'px';
  };
  popup.showPopover();
  position();
  const outside = event => { if (!popup.contains(event.target) && !trigger.contains(event.target)) close(); };
  const escape = event => {
    if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); trigger.focus(); }
  };
  const scroll = event => { if (!popup.contains(event.target)) close(); };
  document.addEventListener('pointerdown', outside);
  popup.parentElement.addEventListener('keydown', escape);
  document.addEventListener('scroll', scroll, true);
  window.addEventListener('resize', position);
  return () => {
    if (popup.matches(':popover-open')) popup.hidePopover();
    document.removeEventListener('pointerdown', outside);
    popup.parentElement?.removeEventListener('keydown', escape);
    document.removeEventListener('scroll', scroll, true);
    window.removeEventListener('resize', position);
  };
};

const DEFAULT_PRIMARY = '#2563eb';

const clamp = (value, min = 0, max = 1) => Math.min(max, Math.max(min, value));

const normalizeHex = (value) => {
  if (typeof value !== 'string' || !/^#[\da-f]{3}(?:[\da-f]{3})?$/i.test(value)) {
    throw new TypeError('primary must be a 3- or 6-digit hex color');
  }
  const hex = value.toLowerCase();
  return hex.length === 4 ? `#${[...hex.slice(1)].map((channel) => channel + channel).join('')}` : hex;
};

const hexToRgb = (hex) => [...hex.slice(1)].reduce((channels, channel, index) => {
  if (index % 2 === 0) channels.push(Number.parseInt(`${channel}${hex[index + 2]}`, 16) / 255);
  return channels;
}, []);

const rgbToHex = (rgb) => `#${rgb.map((channel) => Math.round(clamp(channel) * 255).toString(16).padStart(2, '0')).join('')}`;
const srgbToLinear = (channel) => channel <= .04045 ? channel / 12.92 : ((channel + .055) / 1.055) ** 2.4;
const linearToSrgb = (channel) => channel <= .0031308 ? channel * 12.92 : 1.055 * (Math.max(0, channel) ** (1 / 2.4)) - .055;

const rgbToOklch = (hex) => {
  const [red, green, blue] = hexToRgb(hex).map(srgbToLinear);
  const lightness = .4122214708 * red + .5363325363 * green + .0514459929 * blue;
  const greenCone = .2119034982 * red + .6806995451 * green + .1073969566 * blue;
  const blueCone = .0883024619 * red + .2817188376 * green + .6299787005 * blue;
  const l = Math.cbrt(lightness);
  const m = Math.cbrt(greenCone);
  const s = Math.cbrt(blueCone);
  const a = 1.9779984951 * l - 2.428592205 * m + .4505937099 * s;
  const b = .0259040371 * l + .7827717662 * m - .808675766 * s;
  return {
    l: .2104542553 * l + .793617785 * m - .0040720468 * s,
    c: Math.hypot(a, b),
    h: (Math.atan2(b, a) * 180 / Math.PI + 360) % 360,
  };
};

const oklchToRgb = ({ l, c, h }) => {
  const radians = h * Math.PI / 180;
  const a = c * Math.cos(radians);
  const b = c * Math.sin(radians);
  const lightness = l + .3963377774 * a + .2158037573 * b;
  const greenCone = l - .1055613458 * a - .0638541728 * b;
  const blueCone = l - .0894841775 * a - 1.291485548 * b;
  const lightnessCubed = lightness ** 3;
  const greenConeCubed = greenCone ** 3;
  const blueConeCubed = blueCone ** 3;
  return [
    4.0767416621 * lightnessCubed - 3.3077115913 * greenConeCubed + .2309699292 * blueConeCubed,
    -1.2684380046 * lightnessCubed + 2.6097574011 * greenConeCubed - .3413193965 * blueConeCubed,
    -.0041960863 * lightnessCubed - .7034186147 * greenConeCubed + 1.707614701 * blueConeCubed,
  ].map(linearToSrgb);
};

const oklchToHex = (lch) => {
  const l = clamp(lch.l);
  const c = Math.max(0, lch.c);
  let rgb = oklchToRgb({ ...lch, l, c });
  if (rgb.some((channel) => channel < 0 || channel > 1)) {
    let low = 0;
    let high = c;
    for (let attempt = 0; attempt < 14; attempt += 1) {
      const midpoint = (low + high) / 2;
      const candidate = oklchToRgb({ ...lch, l, c: midpoint });
      if (candidate.every((channel) => channel >= 0 && channel <= 1)) {
        low = midpoint;
        rgb = candidate;
      } else {
        high = midpoint;
      }
    }
  }
  return rgbToHex(rgb);
};

const relativeLuminance = (hex) => hexToRgb(hex).map(srgbToLinear).reduce((total, channel, index) => total + channel * [0.2126, 0.7152, 0.0722][index], 0);
const darkTextLuminance = relativeLuminance('#0f172a');
const contrastFor = (hex) => {
  const luminance = relativeLuminance(hex);
  const whiteContrast = 1.05 / (luminance + .05);
  const darkContrast = (luminance + .05) / (darkTextLuminance + .05);
  return whiteContrast >= Math.max(3.5, darkContrast - 1.35) ? '#ffffff' : '#0f172a';
};
const mix = (first, second, amount) => {
  const one = hexToRgb(first);
  const two = hexToRgb(second);
  return rgbToHex(one.map((channel, index) => channel * amount + two[index] * (1 - amount)));
};

const makePalette = (primary) => {
  const base = normalizeHex(primary);
  const source = rgbToOklch(base);
  const tone = (l, c = source.c) => oklchToHex({ l, c, h: source.h });
  const lightBase = base;
  const lightHover = tone(source.l - .04, source.c * .95);
  const lightDeep = tone(source.l - .1, source.c * .85);
  const lightSoft = tone(source.l + (0.97 - source.l) * .96, source.c * .1);
  const lightText = lightHover;
  const lightBorder = tone(source.l + (0.97 - source.l) * .75, source.c * .2);
  // Keep the brand hue, with readable accents and restrained surface tints at night.
  const darkBase = tone(clamp(source.l, .72, .8), Math.min(source.c * .7, .14));
  const darkHover = tone(clamp(source.l + .06, .78, .86), Math.min(source.c * .6, .12));
  const darkDeep = tone(.32, source.c * .6);
  const darkSoft = mix(darkBase, '#191b1f', .16);
  const darkText = tone(.86, Math.min(source.c * .5, .09));
  const darkBorder = mix(darkBase, '#363b44', .35);
  const darkContrast = '#111214';

  return {
    light: { base: lightBase, hover: lightHover, soft: lightSoft, text: lightText, border: lightBorder, deep: lightDeep, contrast: contrastFor(lightBase) },
    dark: { base: darkBase, hover: darkHover, soft: darkSoft, text: darkText, border: darkBorder, deep: darkDeep, contrast: darkContrast },
  };
};

const primaryTheme = (primary = DEFAULT_PRIMARY) => makePalette(primary);

const setBrandTheme = ({ primary = DEFAULT_PRIMARY } = {}) => {
  const palette = primaryTheme(primary);
  const root = document.documentElement;
  for (const [mode, tokens] of Object.entries(palette)) {
    for (const [role, value] of Object.entries(tokens)) root.style.setProperty(`--se-primary-${mode}${role === 'base' ? '' : `-${role}`}`, value);
  }
  return palette;
};

