    const type = Object.keys(match.groups || {}).find((name) => match.groups[name] !== undefined) || 'keyword';
    result += escapeHtml(source.slice(cursor, match.index));
    result += `<span class="se-token--${type}">${escapeHtml(match[0])}</span>`;
